// EDITE esta lista: cada documento debe ser un texto plano accesible por URL (p. ej. el .txt crudo en GitHub/Drive publico).
// fuente_url es la URL OFICIAL del documento que se mostrara como fuente en el chatbot.
const docs = [
  { titulo: 'Centro de Competencias Digitales UNAB', fuente_url: 'https://unab.edu.co/centro-de-competencias-digitales/', tipo: 'ccd', texto_url: 'https://REEMPLAZAR/ccd.txt' },
  { titulo: 'Reglamento Estudiantil de Pregrado 2019', fuente_url: 'https://unab.edu.co/', tipo: 'reglamento', texto_url: 'https://REEMPLAZAR/reglamento.txt' },
];
return docs.map(d => ({ json: d }));

// La URL oficial se toma de una linea 'Fuente: https://...' / 'URL: https://...' en las primeras lineas del .txt.
const bin = $('Leer .txt locales').all();
return $input.all().map((it, i) => {
  const texto = String(it.json.data || it.json.text || '');
  const nombre = (bin[i] && bin[i].binary && bin[i].binary.data && bin[i].binary.data.fileName) || ('documento_' + i + '.txt');
  const cab = texto.split('\n').slice(0, 6).join('\n');
  const m = cab.match(/(?:fuente|url)\s*:\s*(https?:\/\/\S+)/i) || cab.match(/(https?:\/\/\S+)/);
  const titulo = nombre.replace(/\.txt$/i, '').replace(/[_-]+/g, ' ');
  return { json: { titulo, fuente_url: m ? m[1] : 'https://unab.edu.co/#doc-' + encodeURIComponent(nombre), tipo: 'oficial', texto } };
});

// Fragmentacion por parrafos: hasta 3200 caracteres con solape de 480 (unos 800 y 120 tokens a ~4 caracteres por token en espanol),
// igual que rag/ingesta.py (maximo 800 tokens, solape del 15 %).
const TAM = 3200, SOLAPE = 480;
const salida = [];
for (const it of $input.all()) {
  const texto = String(it.json.texto || '').replace(/\r/g, '').replace(/[ \t]+/g, ' ').trim();
  if (texto.length < 40) continue;
  const parrafos = texto.split(/\n{2,}|\n(?=[A-ZÁÉÍÓÚ0-9#])/).map(p => p.replace(/\n/g, ' ').trim()).filter(Boolean);
  const chunks = []; let actual = '';
  for (let p of parrafos) {
    while (p.length > TAM) { // parrafos enormes: cortar en espacio
      let corte = p.lastIndexOf(' ', TAM); if (corte < TAM / 2) corte = TAM;
      if (actual) { chunks.push(actual); actual = ''; }
      chunks.push(p.slice(0, corte)); p = p.slice(Math.max(0, corte - SOLAPE)).trim();
      if (p.length <= SOLAPE) { p = ''; break; }
    }
    if (!p) continue;
    if ((actual + ' ' + p).length > TAM && actual) { chunks.push(actual); actual = actual.slice(-SOLAPE) + ' ' + p; }
    else actual = actual ? actual + ' ' + p : p;
  }
  if (actual.trim()) chunks.push(actual.trim());
  salida.push({ json: { titulo: it.json.titulo, fuente_url: it.json.fuente_url, tipo: it.json.tipo, chunks } });
}
return salida;

const docs = $('Fragmentar').all();
const ids = $input.all();
const out = [];
docs.forEach((d, i) => {
  const documento_id = ids[i].json.id;
  d.json.chunks.forEach((contenido, n) => out.push({ json: { documento_id, contenido, n, total: d.json.chunks.length, titulo: d.json.titulo, fuente_url: d.json.fuente_url } }));
});
return out;

const frags = $('Un item por fragmento').all();
return $input.all().map((it, i) => {
  const v = it.json.embedding.values;
  if (!Array.isArray(v) || v.length !== 768) throw new Error('Embedding invalido en fragmento ' + i);
  const f = frags[i].json;
  return { json: { documento_id: f.documento_id, contenido: f.contenido,
    metadata: JSON.stringify({ titulo: f.titulo, fuente_url: f.fuente_url, fragmento: f.n + 1, total: f.total }),
    embedding: '[' + v.join(',') + ']' } };
});
